const items = $input.all();

function parseCurrency(val) {
  if (typeof val === 'number') return isNaN(val) ? NaN : val;
  if (typeof val !== 'string') return NaN;
  let s = val.trim().toLowerCase().replace(/,/g, '').replace(/₹/g, '').replace(/rs\.?/g, '').trim();
  if (s.endsWith('crore') || s.endsWith('cr') || s.endsWith('crores')) {
    const num = parseFloat(s.replace(/(crores?|cr)/, '').trim());
    return isNaN(num) ? NaN : Math.round(num * 10000000);
  }
  if (s.endsWith('lakh') || s.endsWith('lakhs') || s.endsWith('lac') || s.endsWith('lacs')) {
    const num = parseFloat(s.replace(/(lakhs?|lacs?)/, '').trim());
    return isNaN(num) ? NaN : Math.round(num * 100000);
  }
  const n = Number(s);
  return isNaN(n) ? NaN : n;
}

function parseYears(val) {
  if (typeof val === 'number') return val;
  if (typeof val !== 'string') return NaN;
  return Number(val.trim().toLowerCase().replace(/(years?|yrs?)/, '').trim());
}

return items.map(item => {
  const data = item.json.body || item.json;
  const errors = [];

  const requestId = data.request_id || "REQ-TENDER-DEMO";
  const tenderId = data.tender_id || (data.tender ? data.tender.tender_id : null) || "TENDER-DEMO-001";
  const bidderId = data.bidder_id || "BIDDER-DEMO-001";
  const bidderName = (data.bidder_name || "ABC Technologies Pvt Ltd").toString().trim();

  // Resolve tender specification block from tender property or root level
  const tenderObj = data.tender || {};
  const rawReqs = tenderObj.requirements || data.tender_requirements || {};
  const rawElig = tenderObj.eligibility || data.eligibility_requirements || {};

  // Check for malformed numeric inputs
  const currencyFields = ['minimum_turnover', 'average_turnover', 'minimum_project_value', 'minimum_net_worth'];
  for (const f of currencyFields) {
    if (rawReqs[f] !== undefined && rawReqs[f] !== null) {
      const parsed = parseCurrency(rawReqs[f]);
      if (isNaN(parsed)) {
        errors.push(`Malformed numeric requirement for '${f}': received non-numeric value '${rawReqs[f]}'`);
      }
    }
  }
  if (rawReqs.minimum_similar_works !== undefined && rawReqs.minimum_similar_works !== null) {
    const num = Number(rawReqs.minimum_similar_works);
    if (isNaN(num)) errors.push(`Malformed numeric requirement for 'minimum_similar_works': received '${rawReqs.minimum_similar_works}'`);
  }
  if (rawReqs.experience_period_years !== undefined && rawReqs.experience_period_years !== null) {
    const y = parseYears(rawReqs.experience_period_years);
    if (isNaN(y)) errors.push(`Malformed numeric requirement for 'experience_period_years': received '${rawReqs.experience_period_years}'`);
  }

  // Deadline validation if present
  const deadline = tenderObj.submission_deadline || data.submission_deadline || null;
  if (deadline) {
    const parsedDate = new Date(deadline);
    if (isNaN(parsedDate.getTime())) {
      errors.push(`Invalid submission_deadline format: '${deadline}'`);
    }
  }

  return {
    json: {
      request_id: requestId,
      tender_id: tenderId,
      bidder_id: bidderId,
      bidder_name: bidderName,
      raw_tender: tenderObj,
      raw_requirements: rawReqs,
      raw_eligibility: rawElig,
      bidder_evidence: {
        financial: data.financial_evidence || data.financial || null,
        experience: data.experience_evidence || data.experience || data.past_projects || data.projects || (data.bidder_evidence ? (data.bidder_evidence.experience || data.bidder_evidence.projects) : null) || null,
        identity: data.identity_evidence || data.identity || null,
        documents: data.documents || null,
        gstin: data.gstin || null,
        pan: data.pan || null,
        udyam: data.udyam || null
      },
      valid_schema: errors.length === 0,
      validation_errors: errors,
      raw_input: data
    }
  };
});

