return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const rawReq = data.raw_requirements || {};
  const rawElig = data.raw_eligibility || {};
  const rawTender = data.raw_tender || {};

  // Financial normalization
  const minTurnover = rawReq.minimum_turnover !== undefined ? parseCurrency(rawReq.minimum_turnover) : (rawReq.average_turnover !== undefined ? parseCurrency(rawReq.average_turnover) : 10000000);
  const minNetWorth = rawReq.minimum_net_worth !== undefined ? parseCurrency(rawReq.minimum_net_worth) : null;

  // Experience normalization
  const minWorks = rawReq.minimum_similar_works !== undefined ? Number(rawReq.minimum_similar_works) : 3;
  const minProjVal = rawReq.minimum_project_value !== undefined ? parseCurrency(rawReq.minimum_project_value) : 1000000;
  const expYears = rawReq.experience_period_years !== undefined ? parseYears(rawReq.experience_period_years) : 5;
  const certReq = rawReq.completion_certificate_required !== undefined ? Boolean(rawReq.completion_certificate_required) : true;

  // Statutory normalization
  const gstReq = rawElig.gst_required !== undefined ? Boolean(rawElig.gst_required) : true;
  const panReq = rawElig.pan_required !== undefined ? Boolean(rawElig.pan_required) : true;
  const udyamReq = rawElig.udyam_required !== undefined ? Boolean(rawElig.udyam_required) : false;

  // Eligibility normalization
  const msmeAllowed = rawReq.msme_allowed !== undefined ? Boolean(rawReq.msme_allowed) : true;
  const startupExempt = rawReq.startup_exemption !== undefined ? Boolean(rawReq.startup_exemption) : false;

  // Submission normalization
  const deadline = rawTender.submission_deadline || null;

  const normalized = {
    financial: {
      minimum_turnover: minTurnover,
      minimum_net_worth: minNetWorth
    },
    experience: {
      minimum_similar_works: minWorks,
      minimum_project_value: minProjVal,
      experience_period_years: expYears,
      completion_certificate_required: certReq
    },
    statutory: {
      gst_required: gstReq,
      pan_required: panReq,
      udyam_required: udyamReq
    },
    eligibility: {
      msme_allowed: msmeAllowed,
      startup_exemption: startupExempt
    },
    submission: {
      submission_deadline: deadline
    }
  };

  return {
    json: {
      ...data,
      normalized_requirements: normalized
    }
  };
});

const items = $input.all();

function parseCurrency(val) {
  if (typeof val === 'number') return isNaN(val) ? NaN : val;
  if (typeof val !== 'string') return NaN;
  let s = val.trim().toLowerCase().replace(/,/g, '').replace(/₹/g, '').replace(/rs\.?/g, '').trim();
  if (s.endsWith('crore') || s.endsWith('cr') || s.endsWith('crores')) {
    const num = parseFloat(s.replace(/(crores?|cr)/, '').trim());
    return isNaN(num) ? NaN : Math.round(num * 10000000);
  }
  if (s.endsWith('lakh') || s.endsWith('lakhs') || s.endsWith('lac') || s.endsWith('lacs')) {
    const num = parseFloat(s.replace(/(lakhs?|lacs?)/, '').trim());
    return isNaN(num) ? NaN : Math.round(num * 100000);
  }
  const n = Number(s);
  return isNaN(n) ? NaN : n;
}

function extractProjectValue(p) {
  if (!p || typeof p !== 'object') return NaN;
  const raw = p.project_value !== undefined ? p.project_value :
              p.value !== undefined ? p.value :
              p.amount !== undefined ? p.amount :
              p.contract_value !== undefined ? p.contract_value :
              p.project_cost !== undefined ? p.project_cost :
              p.cost;
  if (raw === undefined || raw === null) return NaN;
  return parseCurrency(raw);
}

function isSimilarProject(p, isFromSimilarColl = false) {
  if (!p || typeof p !== 'object') return false;

  if (typeof p.similarity === 'boolean') return p.similarity;
  if (typeof p.is_similar === 'boolean') return p.is_similar;
  if (typeof p.similar === 'boolean') return p.similar;

  if (typeof p.similarity === 'string') {
    const s = p.similarity.trim().toLowerCase();
    if (['true', 'yes', 'similar', 'relevant', 'high', 'matched'].includes(s)) return true;
    if (['false', 'no', 'dissimilar', 'not_similar', 'irrelevant', 'low'].includes(s)) return false;
  }
  if (typeof p.is_similar === 'string') {
    const s = p.is_similar.trim().toLowerCase();
    if (['true', 'yes', 'similar'].includes(s)) return true;
    if (['false', 'no', 'not_similar'].includes(s)) return false;
  }
  if (typeof p.similar === 'string') {
    const s = p.similar.trim().toLowerCase();
    if (['true', 'yes', 'similar'].includes(s)) return true;
    if (['false', 'no', 'not_similar'].includes(s)) return false;
  }
  if (typeof p.relevance === 'string') {
    const s = p.relevance.trim().toLowerCase();
    if (['relevant', 'similar', 'high'].includes(s)) return true;
    if (['not_relevant', 'irrelevant', 'low'].includes(s)) return false;
  }

  if (typeof p.similarity === 'number') {
    return p.similarity >= (p.similarity > 1 ? 70 : 0.7);
  }
  if (typeof p.similarity_score === 'number') {
    return p.similarity_score >= (p.similarity_score > 1 ? 70 : 0.7);
  }

  if (isFromSimilarColl) return true;

  return false;
}

const MOCK_BIDDER_PROJECTS = {
  "ABC Technologies Pvt Ltd": [
    {
      project_id: "PROJ-ABC-001",
      project_name: "State Smart City Core Integration",
      client_name: "Urban Development Department",
      project_value: 1500000,
      completion_date: "2024-06-10",
      similarity: true,
      completion_certificate: true,
      certificate_document_id: "DOC-EXP-001"
    },
    {
      project_id: "PROJ-ABC-002",
      project_name: "Enterprise Portal & Security Layer",
      client_name: "Power Distribution Corporation",
      project_value: 1200000,
      completion_date: "2023-08-15",
      similarity: true,
      completion_certificate: true,
      certificate_document_id: "DOC-EXP-002"
    },
    {
      project_id: "PROJ-ABC-003",
      project_name: "Cloud Migration & Managed DevOps",
      client_name: "Municipal Services Department",
      project_value: 1800000,
      completion_date: "2022-11-20",
      similarity: true,
      completion_certificate: true,
      certificate_document_id: "DOC-EXP-003"
    }
  ]
};

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const reqs = data.normalized_requirements || {};
  const ev = data.bidder_evidence || {};

  const passed = [];
  const failed = [];
  const notEvaluated = [];
  const reviewRequired = [];

  let hasEvidence = false;

  // 1. Evaluate Financial Coverage if evidence supplied
  if (ev.financial) {
    hasEvidence = true;
    let actualTurnover = 0;
    if (typeof ev.financial.average_turnover === 'number') {
      actualTurnover = ev.financial.average_turnover;
    } else if (ev.financial.turnover && typeof ev.financial.turnover === 'object') {
      const vals = Object.values(ev.financial.turnover).filter(v => typeof v === 'number');
      if (vals.length > 0) actualTurnover = Math.round(vals.reduce((a, b) => a + b, 0) / vals.length);
    }

    const reqTurnover = reqs.financial?.minimum_turnover || 0;
    if (actualTurnover >= reqTurnover) {
      passed.push(`Financial turnover (₹${actualTurnover.toLocaleString('en-IN')}) meets or exceeds requirement (₹${reqTurnover.toLocaleString('en-IN')})`);
    } else {
      failed.push(`Financial turnover (₹${actualTurnover.toLocaleString('en-IN')}) is below required minimum (₹${reqTurnover.toLocaleString('en-IN')})`);
    }
  } else {
    notEvaluated.push("Financial turnover not evaluated (no bidder financial evidence supplied)");
  }

  // 2. Evaluate Experience Coverage if evidence supplied
  let projects = null;
  let isFromSimilarColl = false;

  if (ev.experience) {
    if (Array.isArray(ev.experience)) {
      projects = ev.experience;
    } else if (typeof ev.experience === 'object') {
      if (Array.isArray(ev.experience.projects)) {
        projects = ev.experience.projects;
      } else if (Array.isArray(ev.experience.similar_projects)) {
        projects = ev.experience.similar_projects;
        isFromSimilarColl = true;
      } else if (Array.isArray(ev.experience.similar_works)) {
        projects = ev.experience.similar_works;
        isFromSimilarColl = true;
      } else if (Array.isArray(ev.experience.past_projects)) {
        projects = ev.experience.past_projects;
      } else if (Array.isArray(ev.experience.contracts)) {
        projects = ev.experience.contracts;
      }
    }
  } else if (Array.isArray(data.past_projects)) {
    projects = data.past_projects;
  } else if (Array.isArray(data.similar_projects)) {
    projects = data.similar_projects;
    isFromSimilarColl = true;
  } else if (Array.isArray(data.projects)) {
    projects = data.projects;
  }

  if (projects === null && MOCK_BIDDER_PROJECTS[data.bidder_name]) {
    projects = MOCK_BIDDER_PROJECTS[data.bidder_name];
  }

  if (projects !== null && Array.isArray(projects)) {
    hasEvidence = true;
    const reqWorks = reqs.experience?.minimum_similar_works || 3;
    const minVal = reqs.experience?.minimum_project_value || 1000000;

    const qualifying = projects.filter(p => {
      const val = extractProjectValue(p);
      const valPass = !isNaN(val) && val >= minVal;
      const simPass = isSimilarProject(p, isFromSimilarColl);
      return valPass && simPass;
    });

    if (qualifying.length >= reqWorks) {
      passed.push(`Similar works count (${qualifying.length}) satisfies requirement (>= ${reqWorks})`);
    } else {
      failed.push(`Similar works count (${qualifying.length}) is below requirement (${reqWorks})`);
    }
  } else {
    notEvaluated.push("Experience criteria not evaluated (no bidder experience evidence supplied)");
  }

  // 3. Evaluate Statutory Coverage
  if (ev.gstin || (ev.identity && ev.identity.gst)) {
    hasEvidence = true;
    if (reqs.statutory?.gst_required) passed.push("GST registration requirement satisfied");
  } else if (reqs.statutory?.gst_required) {
    notEvaluated.push("GST requirement not evaluated (no GST evidence in request)");
  }

  if (ev.pan || (ev.identity && ev.identity.pan)) {
    hasEvidence = true;
    if (reqs.statutory?.pan_required) passed.push("PAN requirement satisfied");
  } else if (reqs.statutory?.pan_required) {
    notEvaluated.push("PAN requirement not evaluated (no PAN evidence in request)");
  }

  return {
    json: {
      ...data,
      coverage_results: {
        evaluated: hasEvidence,
        passed,
        failed,
        not_evaluated: notEvaluated,
        review_required: reviewRequired
      }
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const rawReq = data.raw_requirements || {};
  const rawTender = data.raw_tender || {};
  const ambiguities = [];

  // 1. Conflict detection in requirement definitions (e.g. conflicting turnover thresholds)
  if (rawReq.minimum_turnover && rawReq.average_turnover) {
    if (rawReq.minimum_turnover !== rawReq.average_turnover) {
      ambiguities.push(`TENDER_REQUIREMENT_CONFLICT: Conflicting turnover thresholds defined (minimum: ${rawReq.minimum_turnover} vs average: ${rawReq.average_turnover})`);
    }
  }

  // 2. Submission deadline past check
  const deadline = rawTender.submission_deadline;
  if (deadline) {
    const d = new Date(deadline).getTime();
    const now = Date.now();
    if (!isNaN(d) && d < now) {
      ambiguities.push(`TENDER_DEADLINE_EXPIRED: Submission deadline (${deadline}) has already elapsed`);
    }
  }

  return {
    json: {
      ...data,
      tender_ambiguities: ambiguities
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;

  let status = "VERIFIED";
  let confidence = 0.98;
  let riskLevel = "LOW";
  const allIssues = [];

  if (!data.valid_schema) {
    status = "ERROR";
    confidence = 0.0;
    riskLevel = "HIGH";
    allIssues.push(...(data.validation_errors || ["Invalid tender intelligence request schema"]));
  } else {
    const cov = data.coverage_results || {};
    const ambiguities = data.tender_ambiguities || [];

    // 1. Ambiguities & Conflicts
    if (ambiguities.length > 0) {
      ambiguities.forEach(a => allIssues.push(a));
      if (ambiguities.some(a => a.includes('CONFLICT'))) {
        status = "NOT_VERIFIED";
        riskLevel = "HIGH";
        confidence = 0.70;
      } else {
        status = "REVIEW_REQUIRED";
        riskLevel = "MEDIUM";
        confidence = 0.85;
      }
    }

    // 2. Failed evaluated coverage
    if (cov.failed && cov.failed.length > 0) {
      status = "NOT_VERIFIED";
      riskLevel = "HIGH";
      cov.failed.forEach(f => allIssues.push(f));
    }

    if (allIssues.length === 0) {
      status = "VERIFIED";
      confidence = 0.98;
      riskLevel = "LOW";
    }
  }

  const reqs = data.normalized_requirements || {};
  const cov = data.coverage_results || {
    evaluated: false,
    passed: [],
    failed: [],
    not_evaluated: [],
    review_required: []
  };

  return {
    json: {
      agent: "TENDER_INTELLIGENCE_AGENT",
      status,
      confidence,
      evidence: {
        tender_id: data.tender_id,
        requirements: reqs,
        coverage: cov,
        ambiguities: data.tender_ambiguities || [],
        registry_source: "TENDER_SUBMISSION"
      },
      issues: allIssues,
      risk_level: riskLevel,
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();
return items.map(item => ({
  json: item.json
}));

const items = $input.all();
return items.map(item => ({
  json: {
    agent: "TENDER_INTELLIGENCE_AGENT",
    status: "ERROR",
    confidence: 0.0,
    evidence: {
      error: "Tender intelligence agent encountered an unexpected execution failure",
      fallback_mode: true
    },
    issues: ["Tender intelligence evaluation failed safely"],
    risk_level: "HIGH",
    timestamp: new Date().toISOString()
  }
}));
